# Load packages
library(dplyr)
library(ggplot2)
library(patchwork)
library(readr)

# Define inputs 
# Gene-level pleiotropy metrics generated by 03_calculate_pleiotropy.R.
pleiotropy_file <- file.path(
  "results",
  "gene_pleiotropy_hill_metrics.csv"
)

# Gene-trait effect table generated by 02_build_gene_trait_effects.R.
gene_trait_file <- file.path(
  "results",
  "gene_trait_collapsed.csv"
)

# Readable per-gene trait table generated by 02_build_gene_trait_effects.R.
gene_trait_table_file <- file.path(
  "results",
  "gene_trait_table.csv"
)

# Merged pleiotropy and co-expression dataset generated by 04_analyze_network_centrality.R.
network_file <- file.path(
  "results",
  "merged_hill_coexp.csv"
)

# Define outputs 
# Manuscript Figure 1.
figure_pdf_file <- file.path(
  "figures",
  "Figure_1.pdf"
)

figure_jpg_file <- file.path(
  "figures",
  "Figure_1.jpg"
)

# Manuscript Table 1.
table_file <- file.path(
  "results",
  "Table_1_top_pleiotropic_genes.csv"
)

# Create output directories 
dir.create(
  "results",
  showWarnings = FALSE
)

dir.create(
  "figures",
  showWarnings = FALSE
)


# Load data 
pleiotropy_metrics <- read_csv(
  pleiotropy_file,
  show_col_types = FALSE
)

gene_trait_effects <- read_csv(
  gene_trait_file,
  show_col_types = FALSE
)

gene_trait_table <- read_csv(
  gene_trait_table_file,
  show_col_types = FALSE
)

network_data <- read_csv(
  network_file,
  show_col_types = FALSE
)

# Create Table 1
# Select the five genes with the highest Hill q = 1 values and attach their readable ontology-trait summaries.
table_1 <- pleiotropy_metrics %>%
  arrange(
    desc(hill_q1)
  ) %>%
  slice_head(
    n = 5
  ) %>%
  left_join(
    gene_trait_table,
    by = "gene"
  )

# Save Table 1.
write.csv(
  table_1,
  table_file,
  row.names = FALSE
)

# Prepare Figure 1 data 
# Panel A data: Hill q = 1 values.
hill_df <- pleiotropy_metrics %>%
  select(
    gene,
    hill_q1
  )

# Panel B data: number of unique ontology traits associated with each gene.
# gene_trait_collapsed.csv contains one row per unique gene-trait pair, so counting rows within each gene gives trait richness.
traits_per_gene <- gene_trait_effects %>%
  count(
    gene,
    name = "n_traits"
  )

# Panel C data: trait richness and Hill q = 1 for the same genes.
hill_vs_traits <- traits_per_gene %>%
  inner_join(
    hill_df,
    by = "gene"
  )

# Panel D data: Hill q = 1 and co-expression network degree.
panel_d_df <- network_data %>%
  select(
    gene,
    hill_q1,
    node_degree
  )

# Create Figure 1 panels
# Panel A: distribution of Hill q = 1.
pA <- ggplot(
  hill_df,
  aes(
    x = hill_q1
  )
) +
  geom_histogram(
    binwidth = 0.5,
    fill = "grey70",
    color = "black"
  ) +
  theme_classic() +
  labs(
    x = "Hill q = 1",
    y = "Number of genes",
    title = "A"
  )

# Panel B: distribution of trait richness.
pB <- ggplot(
  traits_per_gene,
  aes(
    x = n_traits
  )
) +
  geom_histogram(
    binwidth = 1,
    fill = "grey70",
    color = "black"
  ) +
  theme_classic() +
  labs(
    x = "Number of traits per gene",
    y = "Number of genes",
    title = "B"
  )

# Panel C: Hill q = 1 versus trait richness.
# The fitted linear trend is included for visualization. Statistical associations are evaluated separately using Spearman correlations.
pC <- ggplot(
  hill_vs_traits,
  aes(
    x = n_traits,
    y = hill_q1
  )
) +
  geom_point(
    alpha = 0.4,
    size = 0.6
  ) +
  geom_smooth(
    method = "lm",
    se = FALSE,
    color = "red"
  ) +
  theme_classic() +
  labs(
    x = "Number of traits per gene",
    y = "Hill q = 1",
    title = "C"
  )

# Panel D: Hill q = 1 versus co-expression network degree.
# The fitted linear trend is included for visualization. The reported association is evaluated using Spearman rank correlation in 04_analyze_network_centrality.R.
pD <- ggplot(
  panel_d_df,
  aes(
    x = hill_q1,
    y = node_degree
  )
) +
  geom_point(
    alpha = 0.4,
    size = 0.6
  ) +
  geom_smooth(
    method = "lm",
    se = FALSE,
    color = "red"
  ) +
  theme_classic() +
  labs(
    x = "Hill q = 1",
    y = "Gene co-expression degree",
    title = "D"
  )

# Combine Figure 1 panels 
final_figure <- (
  pA | pB
) / (
  pC | pD
)

# Save Figure 1 
# Save a PDF 
ggsave(
  filename = figure_pdf_file,
  plot = final_figure,
  width = 8,
  height = 8,
  units = "in"
)

# Save a high-resolution JPEG
ggsave(
  filename = figure_jpg_file,
  plot = final_figure,
  device = ragg::agg_jpeg,
  width = 8.5,
  height = 8.5,
  units = "in",
  dpi = 600
)
